verification_tests:
from target import apply_overrides


def test_nested_override_keeps_other_nested_keys():
    assert apply_overrides(
        {"server": {"port": 80, "host": "a"}}, {"server": {"port": 8080}}
    ) == {"server": {"port": 8080, "host": "a"}}


def test_two_level_nested_override_is_merged():
    assert apply_overrides(
        {"db": {"pool": {"size": 5, "max": 10}}}, {"db": {"pool": {"size": 20}}}
    ) == {"db": {"pool": {"size": 20, "max": 10}}}


def test_top_level_override_replaces_scalar():
    assert apply_overrides({"debug": False}, {"debug": True}) == {"debug": True}
